}

package com.designhub.platform.controller;

import com.designhub.platform.dto.ApiResponse;
import com.designhub.platform.entity.FileInfo;
import com.designhub.platform.entity.User;
import com.designhub.platform.mapper.UserMapper;
import com.designhub.platform.service.FileService;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;

import java.io.FileNotFoundException;
import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/files")
public class FileController {

    private final FileService fileService;

    private final UserMapper userMapper;

    public FileController(FileService fileService, UserMapper userMapper) {
        this.fileService = fileService;
        this.userMapper = userMapper;
    }

    @PostMapping("/upload")
    public ApiResponse<Map<String, Object>> upload(@RequestParam("file") MultipartFile file,
                                                   @RequestParam("projectId") Long projectId,
                                                   Authentication authentication) {
        User uploader = userMapper.selectByUsername(authentication.getName());
        try {
            FileInfo fileInfo = fileService.upload(file, projectId, uploader.getId());
            Map<String, Object> data = new LinkedHashMap<>();
            data.put("id", fileInfo.getId());
            data.put("projectId", fileInfo.getProjectId());
            data.put("originalName", fileInfo.getOriginalName());
            data.put("fileSize", fileInfo.getFileSize());
            data.put("contentType", fileInfo.getContentType());
            data.put("createdAt", fileInfo.getCreatedAt().toString());
            return ApiResponse.success("上传成功", data);
        } catch (FileService.UnsupportedFileTypeException e) {
            return ApiResponse.error(400, "不支持的文件类型");
        } catch (IOException e) {
            return ApiResponse.error(500, "文件上传失败");
        }
    }

    @GetMapping("/{id}/preview")
    public ResponseEntity<?> preview(@PathVariable("id") Long id) {
        FileInfo fileInfo = fileService.getById(id);
        if (fileInfo == null) {
            return jsonEnvelope(ApiResponse.error(404, "文件不存在"));
        }
        try {
            byte[] content = fileService.readPreviewContent(fileInfo);
            return ResponseEntity.ok()
                    .contentType(MediaType.parseMediaType(fileService.previewContentType(fileInfo)))
                    .body(content);
        } catch (FileNotFoundException e) {
            return jsonEnvelope(ApiResponse.error(404, "文件不存在"));
        } catch (IOException e) {
            return jsonEnvelope(ApiResponse.error(500, "文件读取失败"));
        }
    }

    @GetMapping("/project/{projectId}")
    public ApiResponse<List<FileInfo>> listByProject(@PathVariable("projectId") Long projectId) {
        return ApiResponse.success(fileService.getByProjectId(projectId));
    }

    @GetMapping("/{id}")
    public ApiResponse<FileInfo> detail(@PathVariable("id") Long id) {
        FileInfo fileInfo = fileService.getById(id);
        if (fileInfo == null) {
            return ApiResponse.error(404, "文件不存在");
        }
        return ApiResponse.success(fileInfo);
    }

    @DeleteMapping("/{id}")
    public ApiResponse<Void> delete(@PathVariable("id") Long id) {
        FileInfo fileInfo = fileService.getById(id);
        if (fileInfo == null) {
            return ApiResponse.error(404, "文件不存在");
        }
        try {
            fileService.delete(fileInfo);
            return ApiResponse.success("删除成功", null);
        } catch (IOException e) {
            return ApiResponse.error(500, "文件删除失败");
        }
    }

    private ResponseEntity<ApiResponse<Void>> jsonEnvelope(ApiResponse<Void> envelope) {
        return ResponseEntity.ok()
                .contentType(MediaType.APPLICATION_JSON)
                .body(envelope);
    }
}

package com.designhub.platform.controller;

import com.designhub.platform.dto.ApiResponse;
import com.designhub.platform.dto.CreateProjectRequest;
import com.designhub.platform.entity.Project;
import com.designhub.platform.entity.User;
import com.designhub.platform.mapper.UserMapper;
import com.designhub.platform.service.ProjectService;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

@RestController
@RequestMapping("/api/projects")
public class ProjectController {

    private final ProjectService projectService;

    private final UserMapper userMapper;

    public ProjectController(ProjectService projectService, UserMapper userMapper) {
        this.projectService = projectService;
        this.userMapper = userMapper;
    }

    @PostMapping
    @PreAuthorize("hasRole('ADMIN')")
    public ApiResponse<Project> create(@RequestBody CreateProjectRequest request, Authentication authentication) {
        User owner = userMapper.selectByUsername(authentication.getName());
        Project project = projectService.createProject(request.getName(), request.getDescription(), owner.getId());
        return ApiResponse.success("创建成功", project);
    }

    @GetMapping
    public ApiResponse<List<Project>> list() {
        return ApiResponse.success(projectService.listProjects());
    }

    @GetMapping("/{id}")
    public ApiResponse<Project> detail(@PathVariable("id") Long id) {
        Project project = projectService.getProjectById(id);
        if (project == null) {
            return ApiResponse.error(404, "项目不存在");
        }
        return ApiResponse.success(project);
    }
}

package com.designhub.platform.dto;

import lombok.Data;

@Data
public class ApiResponse<T> {

    private int code;

    private String message;

    private T data;

    public static <T> ApiResponse<T> success(T data) {
        return of(200, "success", data);
    }

    public static <T> ApiResponse<T> success(String message, T data) {
        return of(200, message, data);
    }

    public static <T> ApiResponse<T> error(int code, String message) {
        return of(code, message, null);
    }

    private static <T> ApiResponse<T> of(int code, String message, T data) {
        ApiResponse<T> response = new ApiResponse<>();
        response.setCode(code);
        response.setMessage(message);
        response.setData(data);
        return response;
    }
}

